	if file, ok := value.(UploadFile); ok {
		return writeMultipartPart(w, key, file.Filename, file.ContentType, file.Data)
	}
	if file, ok := value.(*UploadFile); ok {
		return writeMultipartPart(w, key, file.Filename, file.ContentType, file.Data)
	}
	if structured, ok := value.(multipartJSON); ok {
		encoded, err := json.Marshal(structured.Value)
		if err != nil {
			return fmt.Errorf("encode multipart field %q: %w", key, err)
		}
		return writeMultipartPart(w, key, "", structured.ContentType, encoded)
	}
	if bytesValue, ok := value.([]byte); ok {
		return writeMultipartPart(w, key, key, "application/octet-stream", bytesValue)
	}
	rv := reflect.ValueOf(value)
	if rv.Kind() == reflect.Pointer {
		return writeMultipartValue(w, key, rv.Elem().Interface())
	}
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		for i := 0; i < rv.Len(); i++ {
			if err := writeMultipartValue(w, key, rv.Index(i).Interface()); err != nil {
				return err
			}
		}
		return nil
	}
	return writeMultipartPart(w, key, "", "", []byte(scalarString(value)))
